const out = [];
for (const item of $input.all()) {
  const e = item.json, bin = item.binary || {};
  for (const [k, b] of Object.entries(bin)) {
    if (!/pdf|image\/(png|jpe?g|webp)/i.test(b.mimeType || '')) continue;
    out.push({ json: { message_id: e.id, thread_id: e.threadId, from: e.from?.value?.[0]?.address || e.from?.text || '',
      subject: e.subject || '', received_at: e.date || new Date().toISOString(), file_name: b.fileName || `${k}.pdf`, mime: b.mimeType },
      binary: { invoice: b } });
  }
}
return out;

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const b64 = (await this.helpers.getBinaryDataBuffer(i, 'invoice')).toString('base64');
  const isPdf = /pdf/i.test(it.json.mime);
  const part = isPdf ? { type: 'file', file: { filename: it.json.file_name, file_data: `data:application/pdf;base64,${b64}` } }
                     : { type: 'image_url', image_url: { url: `data:${it.json.mime};base64,${b64}`, detail: 'high' } };
  out.push({ json: { ...it.json, ai_body: { model: 'gpt-4o', temperature: 0, response_format: { type: 'json_object' }, messages: [
    { role: 'system', content: `You extract data from Indian GST tax invoices (digital or scanned). Return ONLY JSON:
{"is_invoice": boolean, "vendor_name": string, "vendor_gstin": string|null, "buyer_gstin": string|null, "invoice_no": string, "invoice_date": "YYYY-MM-DD",
 "po_number": string|null, "place_of_supply": string|null, "irn": string|null, "currency": "INR",
 "lines": [{"description": string, "hsn": string|null, "qty": number, "uom": string|null, "unit_price": number, "taxable_value": number, "gst_rate": number}],
 "taxable_total": number, "cgst": number, "sgst": number, "igst": number, "cess": number, "round_off": number, "grand_total": number,
 "bank_account": string|null, "ifsc": string|null, "confidence": number (0-1)}
Copy numbers exactly as printed, without currency symbols. Use 0 for absent taxes. Use null when a value is not printed. Never guess.` },
    { role: 'user', content: [{ type: 'text', text: `Extract this invoice. Email subject: ${it.json.subject}` }, part] } ] } } });
}
return out;

const src = $('Prepare AI Extraction').item.json;
let x = {};
try { x = JSON.parse($json.choices?.[0]?.message?.content || '{}'); } catch (e) { x = { is_invoice: false }; }
const n = v => Math.round((Number(String(v ?? 0).replace(/[^\d.\-]/g, '')) || 0) * 100) / 100;
const { ai_body, ...meta } = src;
return { json: { ...meta, ...x, vendor_gstin: String(x.vendor_gstin || '').toUpperCase().replace(/\s/g, ''),
  buyer_gstin: String(x.buyer_gstin || '').toUpperCase().replace(/\s/g, ''), invoice_no: String(x.invoice_no || '').trim(),
  lines: (x.lines || []).map(l => ({ ...l, qty: n(l.qty), unit_price: n(l.unit_price), taxable_value: n(l.taxable_value), gst_rate: n(l.gst_rate) })),
  taxable_total: n(x.taxable_total), cgst: n(x.cgst), sgst: n(x.sgst), igst: n(x.igst), cess: n(x.cess), round_off: n(x.round_off), grand_total: n(x.grand_total),
  extraction_ok: !!x.is_invoice && !!x.invoice_no && n(x.grand_total) > 0 } };

const cfg = {
  buyer_gstin: 'REPLACE_WITH_YOUR_GSTIN',            // e.g. 36AAACX1234X1Z5
  auto_approve_limit: 50000, price_warn_pct: 2, price_hold_pct: 10, qty_tol: 0, tax_tol: 2, default_terms: 30,
  approvers: [[200000, 'Finance Manager'], [Infinity, 'CFO']],
  tds_rates: { '194C': 2, '194C-IND': 1, '194J': 10, '194J-TECH': 2, '194I': 10, '194H': 5, '194Q': 0.1 },
  approval_webhook: 'https://REPLACE-N8N-DOMAIN/webhook/ap-approval'
};
const CH = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const gstinOk = g => { if (!/^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(g)) return false;
  let s = 0; for (let i = 0; i < 14; i++) { const p = CH.indexOf(g[i]) * (i % 2 ? 2 : 1); s += Math.floor(p / 36) + (p % 36); }
  return CH[(36 - (s % 36)) % 36] === g[14]; };
const r2 = x => Math.round(x * 100) / 100;
const norm = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const toks = s => new Set(String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 2));
const jacc = (a, b) => { const A = toks(a), B = toks(b); const i = [...A].filter(x => B.has(x)).length; return A.size + B.size ? i / (A.size + B.size - i) : 0; };
const vendors = $('Read Vendor Master').all().map(i => i.json).filter(v => v.vendor_code || v.gstin);
const pos = $('Read Purchase Orders').all().map(i => i.json).filter(p => p.po_number);
const grns = $('Read GRNs').all().map(i => i.json).filter(g => g.po_number);
const ledger = $('Read AP Ledger').all().map(i => i.json).filter(l => l.invoice_key);
const archived = $('Archive Invoice to Drive').all();
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const billedBefore = {};
ledger.filter(l => !/rejected/i.test(l.status || '')).forEach(l => { try { JSON.parse(l.billed_lines || '[]').forEach(b => {
  const k = `${norm(l.po_number)}|${b.po_line}`; billedBefore[k] = (billedBefore[k] || 0) + Number(b.qty || 0); }); } catch (e) {} });

return $('Parse Extracted Fields').all().map((it, idx) => {
  const x = it.json, crit = [], warn = [], matches = [];
  if (!x.extraction_ok) crit.push('Could not read the invoice reliably (not an invoice or low quality)');
  const v = vendors.find(m => norm(m.gstin) === x.vendor_gstin) || vendors.find(m => jacc(m.vendor_name, x.vendor_name) >= 0.5) || null;
  if (!x.vendor_gstin) crit.push('Vendor GSTIN missing'); else if (!gstinOk(x.vendor_gstin)) crit.push(`Vendor GSTIN ${x.vendor_gstin} fails checksum`);
  if (x.buyer_gstin && x.buyer_gstin !== cfg.buyer_gstin) crit.push(`Billed to GSTIN ${x.buyer_gstin}, not ours`);
  if (!v) crit.push('Vendor not in the vendor master'); else if (x.vendor_gstin && norm(v.gstin) !== x.vendor_gstin) warn.push('Vendor matched by name; GSTIN differs from master');
  if (v && x.bank_account && v.bank_account && norm(v.bank_account) !== norm(x.bank_account)) crit.push(`⚠️ Bank account on invoice (${x.bank_account}) ≠ vendor master. Possible fraud, verify by phone`);
  const key = `${x.vendor_gstin || norm(x.vendor_name)}|${norm(x.invoice_no)}`;
  if (ledger.some(l => l.invoice_key === key)) crit.push('Duplicate: this vendor + invoice number is already in the ledger');
  else if (ledger.some(l => l.vendor_gstin === x.vendor_gstin && Number(l.total) === x.grand_total && l.invoice_date === x.invoice_date)) warn.push('Possible duplicate: same vendor, amount and date');

  // ---- tax maths ----
  const intra = x.vendor_gstin.slice(0, 2) === cfg.buyer_gstin.slice(0, 2);
  const lineTaxable = r2(x.lines.reduce((a, l) => a + (l.taxable_value || l.qty * l.unit_price), 0));
  const expTax = r2(x.lines.reduce((a, l) => a + (l.taxable_value || l.qty * l.unit_price) * l.gst_rate / 100, 0));
  const gotTax = r2(x.cgst + x.sgst + x.igst);
  if (Math.abs(lineTaxable - x.taxable_total) > cfg.tax_tol) warn.push(`Line total ₹${lineTaxable} ≠ taxable ₹${x.taxable_total}`);
  if (Math.abs(expTax - gotTax) > cfg.tax_tol) crit.push(`GST charged ₹${gotTax} ≠ expected ₹${expTax} from line rates`);
  if (intra && x.igst > 0) crit.push('IGST charged on an intra-state supply (should be CGST+SGST)');
  if (!intra && (x.cgst > 0 || x.sgst > 0)) crit.push('CGST/SGST charged on an inter-state supply (should be IGST)');
  if (Math.abs(r2(x.taxable_total + gotTax + x.cess + x.round_off) - x.grand_total) > cfg.tax_tol) warn.push('Grand total does not add up');
  if (x.taxable_total > 500000 && !x.irn) warn.push('No IRN printed. Check whether the vendor is required to e-invoice');

  // ---- PO + GRN ----
  const poLines = pos.filter(p => norm(p.po_number) === norm(x.po_number));
  const billed = [];
  if (!x.po_number) { if (!v || String(v.po_required || 'yes').toLowerCase() !== 'no') crit.push('No PO number on the invoice'); }
  else if (!poLines.length) crit.push(`PO ${x.po_number} not found`);
  else for (const l of x.lines) {
    const best = poLines.map(p => ({ p, s: (l.hsn && p.hsn && String(p.hsn).slice(0, 4) === String(l.hsn).slice(0, 4) ? 0.5 : 0) + jacc(p.item, l.description) }))
      .sort((a, b) => b.s - a.s)[0];
    if (!best || best.s < 0.25) { crit.push(`Line "${l.description}" not on PO ${x.po_number}`); continue; }
    const p = best.p, poPrice = Number(p.unit_price), pv = poPrice ? r2((l.unit_price - poPrice) / poPrice * 100) : 0;
    const received = grns.filter(g => norm(g.po_number) === norm(x.po_number) && jacc(g.item, p.item) >= 0.5).reduce((a, g) => a + Number(g.qty_received || 0), 0);
    const already = billedBefore[`${norm(x.po_number)}|${p.line_no || p.item}`] || 0;
    const avail = received - already;
    if (pv > cfg.price_hold_pct) crit.push(`${p.item}: price ₹${l.unit_price} is ${pv}% above PO ₹${poPrice}`);
    else if (pv > cfg.price_warn_pct) warn.push(`${p.item}: price ${pv}% above PO`);
    if (Number(p.gst_rate) && Number(p.gst_rate) !== l.gst_rate) warn.push(`${p.item}: GST ${l.gst_rate}% vs PO ${p.gst_rate}%`);
    if (!received) crit.push(`${p.item}: no GRN, goods not received yet`);
    else if (l.qty > avail + cfg.qty_tol) crit.push(`${p.item}: billed ${l.qty} > received ${received} − already billed ${already}`);
    matches.push(`${p.item}: qty ${l.qty}/${avail} avail · ₹${l.unit_price} vs PO ₹${poPrice}${pv ? ` (${pv > 0 ? '+' : ''}${pv}%)` : ''}`);
    billed.push({ po_line: p.line_no || p.item, qty: l.qty });
  }

  // ---- TDS, due date, decision ----
  const sec = String(v?.tds_section || '').toUpperCase();
  const tdsRate = cfg.tds_rates[sec] ?? 0;
  const tds = r2(x.taxable_total * tdsRate / 100);
  const due = DateTime.fromISO(x.invoice_date || $now.toISODate()).plus({ days: Number(v?.payment_terms_days) || cfg.default_terms });
  const decision = crit.length ? 'on_hold' : (warn.length || x.grand_total > cfg.auto_approve_limit) ? 'needs_approval' : 'auto_approved';
  const approver = cfg.approvers.find(([lim]) => x.grand_total <= lim)[1];
  const token = hex(24);
  const link = a => `${cfg.approval_webhook}?id=${encodeURIComponent(key)}&t=${token}&a=${a}`;
  return { json: { ...x, invoice_key: key, vendor_code: v?.vendor_code || '', vendor_email: v?.email || x.from, vendor_master_name: v?.vendor_name || x.vendor_name,
    supply: intra ? 'Intra-state (CGST+SGST)' : 'Inter-state (IGST)', expected_tax: expTax, tds_section: sec || 'none', tds_rate: tdsRate,
    tds_amount: tds, net_payable: r2(x.grand_total - tds), due_date: due.toFormat('yyyy-LL-dd'), decision,
    status: decision === 'auto_approved' ? 'approved' : decision === 'needs_approval' ? 'pending_approval' : 'on_hold',
    exceptions: crit, warnings: warn, match_summary: matches, billed_lines: JSON.stringify(billed), approver, token,
    approve_url: link('approve'), reject_url: link('reject'), file_link: archived[idx]?.json?.webViewLink || '' } };
});

const m = $('3-Way Match & GST/TDS Checks').item.json;
const inr = v => '₹' + Number(v).toLocaleString('en-IN');
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `Invoice approval · ${m.vendor_master_name}`.slice(0, 150) } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Invoice*\n${m.invoice_no} · ${m.invoice_date}` }, { type: 'mrkdwn', text: `*Amount*\n${inr(m.grand_total)} (net ${inr(m.net_payable)})` },
    { type: 'mrkdwn', text: `*PO*\n${m.po_number || '–'}` }, { type: 'mrkdwn', text: `*Due / Approver*\n${m.due_date} · ${m.approver}` } ] },
  { type: 'section', text: { type: 'mrkdwn', text: `*Why approval:* ${m.warnings.length ? m.warnings.map(w => `\n• ${w}`).join('') : `\n• Amount above the auto-approve limit`}` } },
  ...(m.match_summary.length ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: m.match_summary.slice(0, 6).join('\n') }] }] : []),
  { type: 'context', elements: [{ type: 'mrkdwn', text: `${m.supply} · GST ₹${r(m.cgst + m.sgst + m.igst)} · TDS ${m.tds_section} ${inr(m.tds_amount)}` }] },
  { type: 'actions', elements: [
    { type: 'button', style: 'primary', text: { type: 'plain_text', text: '✅ Approve' }, url: m.approve_url },
    { type: 'button', style: 'danger', text: { type: 'plain_text', text: '❌ Reject' }, url: m.reject_url },
    ...(m.file_link ? [{ type: 'button', text: { type: 'plain_text', text: '📄 View invoice' }, url: m.file_link }] : []) ] } ];
function r(v) { return Math.round(v * 100) / 100; }
return { json: { blocks, fallback: `Approve invoice ${m.invoice_no} from ${m.vendor_master_name} for ${inr(m.grand_total)}` } };

