const q = $('On Approve or Reject Link Click').first().json.query || {};
const l = $input.first()?.json || {};
const a = String(q.a || '').toLowerCase();
let reason = '';
if (!l.invoice_key) reason = 'Invoice not found';
else if (l.status !== 'pending_approval') reason = `Already ${l.status}`;
else if (!l.token || l.token === 'used' || l.token !== q.t) reason = 'Invalid or expired link';
else if (!['approve', 'reject'].includes(a)) reason = 'Unknown action';
return [{ json: { ...l, act: a, valid: !reason, reason, new_status: a === 'approve' ? 'approved' : 'rejected' } }];

const horizon = $now.plus({ days: 7 }).toISODate();
const batch = `PAY-${$now.toFormat('yyyyLLdd')}`;
const vendors = Object.fromEntries($('Read Vendor Bank Details').all().map(i => [i.json.vendor_code, i.json]));
const due = $('Read AP Ledger (Payables)').all().map(i => i.json)
  .filter(l => l.status === 'approved' && !l.payment_batch && String(l.due_date) <= horizon);
const g = {};
due.forEach(l => (g[l.vendor_code || l.vendor_gstin] = g[l.vendor_code || l.vendor_gstin] || []).push(l));
return Object.entries(g).map(([code, list]) => {
  const v = vendors[code] || {};
  const amt = Math.round(list.reduce((a, l) => a + Number(l.net_payable || 0), 0) * 100) / 100;
  return { json: { 'Batch ID': batch, 'Beneficiary Name': v.vendor_name || list[0].vendor_name, 'Account Number': v.bank_account || '',
    'IFSC': v.ifsc || '', 'Amount': amt, 'Payment Mode': amt >= 200000 ? 'RTGS' : 'NEFT', 'Beneficiary Email': v.email || '',
    'Narration': `Inv ${list.map(l => l.invoice_no).join(',')}`.slice(0, 30), 'TDS Deducted': Math.round(list.reduce((a, l) => a + Number(l.tds_amount || 0), 0) * 100) / 100,
    'Invoice Refs': list.map(l => l.invoice_key).join(';'), 'Bank Details OK': v.bank_account && v.ifsc ? 'YES' : 'MISSING' } };
});

